reference_solution.environments.tf:
variable "environment" {
  type        = string
  default     = "dev"
  description = "Deployment environment: must be dev, staging, or prod"
}

locals {
  environment_config = {
    dev = {
      instance_count = 1
      instance_size  = "small"
    }
    staging = {
      instance_count = 2
      instance_size  = "medium"
    }
    prod = {
      instance_count = 5
      instance_size  = "large"
    }
  }

  selected = lookup(local.environment_config, var.environment, local.environment_config["dev"])
}

output "instance_count" {
  value = local.selected.instance_count
}

output "instance_size" {
  value = local.selected.instance_size
}

